function OverseaManageMerchantFriendDialog:Awake()
    SetListViewAction(self.LoopListFriend, Bind(self, self.OnUpdateRightListCellHandler_), FriendCellPath)
    SetButtonAction(self.BtnRandomVisit.gameObject,Bind(self,self.OnBtnRandomVisitClick))
