function OverseaManageMerchantFriendDialog:FreshTab()
    ---@type CommonTabToggleLeft
    local env = CfUtils.GetLuaScr(self.CommonTabToggleLeft.gameObject, CommonTabToggleLeftPath)
    if isNull(env) then return end
    local toggleData = self:InitToggleData()
    env:SetAfterAction(function(index)
        self:RefreshRightShow(index + 1)
    end)
    env:FillToggles(toggleData,1,nil,true)
end

function OverseaManageMerchantFriendDialog:InitToggleData()
    local toggleData = {}
    for i = 1, #Config do
        ---是否解锁的逻辑
        local redPointNode = self:GetTabRedPointByIndex(i)
        table.insert(toggleData, { text = Config[i].name, lock = false, textDefStatus = Config[i].textDefStatus, redPointStrNode = redPointNode, func = function(isSelect, index)
            self:RefreshRightShow(index)
            return 1
        end })
    end
    return toggleData
end

function OverseaManageMerchantFriendDialog:GetTabRedPointByIndex(i)
    if i == TabType.Friend then
        return nil
    else
        return Constants.RedPointConst.MaidCafeCattyCallOnRecord
    end
end

function OverseaManageMerchantFriendDialog:RefreshRightShow(index)
    if not isNull(self.curIndex) and self.curIndex == index then
        return
    end
    self.curIndex = index
    self:FreshListShow()
    CfUtils.SetUISwitchText(self.TxtEmpty,self.curIndex)
end

