function OverseaManageMerchantFriendDialog:FreshFilterNode()
    ---@type UIAreaFilterMB
    local filterNodeEnv = self:GetFilterNodeEnv()
    if isNull(filterNodeEnv) then return end
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local permission = maidCoffeeComponent:GetVisitPermission()
    filterNodeEnv.selectIndex = permission
    ---@type UICommonFilterMB
    local sortType = Constants.UISortType.CallOnType
    filterNodeEnv:SetFilterClass(Constants.UIFilterType.CallOnType)
    filterNodeEnv:SetImgAllow(true)
    filterNodeEnv:SetCallback(function(index)
        self.type = filterNodeEnv.selectIndex
        GameUtils.Request(Interfaces.OverseaCafeSetVisitPermission,{visitPermission = self.type},function(request,response)
            if checkNumber(response.errCode) == 0 then
                maidCoffeeComponent:UpdateVisitPermission(self.type)
            end
        end)
    end, sortType)
    filterNodeEnv:RefreshUI()
end

---GetFilterNodeEnv
---@return UIAreaFilterMB
function OverseaManageMerchantFriendDialog:GetFilterNodeEnv()
    if isNull(self._filterNodeEnv) then
        self._filterNodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBEnvPath)
    end
    return self._filterNodeEnv
end

function OverseaManageMerchantFriendDialog:RefreshShow()
    self:FreshFilterNode()
    self:FreshTab()
    self:FreshUIShow()

end

function OverseaManageMerchantFriendDialog:FreshUIShow()
    CfUtils.FillText(self.TxtState,localize("每日5点更新"))
    local timesVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 56)
    local totalTimes = checkNumber(timesVo.num)
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local haveCallOnTimes = maidCoffeeHomeDojo:GetRandomVisitedTimes()
    CfUtils.FillText(self.TxtFrequency,string.format("<color=#FFFFFF>%s</color>/%s",math.max(0,totalTimes - haveCallOnTimes) ,totalTimes))
end

function OverseaManageMerchantFriendDialog:FreshListShow()
    local interface = Config[self.curIndex].interfaces
    GameUtils.Request(interface,{},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local data = self.curIndex == TabType.Friend and response.data.friends or response.data.records
            self.curData = data
            local count = table.count(data)
            CfUtils.SetActive(self.ItemEmptyPanel,not (count > 0))
            CfUtils.SetActive(self.LoopListFriend,count > 0)
            if count > 0 then
                GameUtils.ReloadData(self.LoopListFriend,count)
            end
        end
    end)
end

