    local cellNode = listView:NewListViewItem(CellNodeName)
    local cellData = checkTable(self.curData[luaIndex])
    ---@type LadderCompetionTaskRewardCellNode
    local cellEnv = CfUtils.GetLuaScr(cellNode, FriendCellPath)
    if cellEnv then
        cellEnv:SetLuaIndexAndData(luaIndex,cellData,self.curIndex)
        cellEnv:SetClickCB(Bind(self, self.OnClickCellAction))
        -- init anim
      --[[  if listView.DisplayItemNumber < listView.DisplayItemCount then
            cellEnv:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            cellEnv:PlayAnimByIdle()
        end]]
    end
    return cellNode
end

